"""Second independent reference: pure-Python bitsets, exhaustive clause enumeration.

Deliberately different in structure from both the submission and brute.py:
 * universe enumerated by decoding mixed-radix indices,
 * duplicate training records kept as separate bits,
 * every subset up to width enumerated exhaustively (no pruning at all),
 * decoding by per-target-value statistics collected with plain Python loops.
"""
import itertools

CMP = {'eq': lambda a, b: a == b, 'ne': lambda a, b: a != b, 'lt': lambda a, b: a < b,
       'le': lambda a, b: a <= b, 'gt': lambda a, b: a > b, 'ge': lambda a, b: a >= b}


class Ref:
    def __init__(self, job):
        self.fields = job['fields']
        self.F = len(self.fields)
        self.K = int(job['slots'])
        self.C = self.F * self.K
        self.names = [f['name'] for f in self.fields]
        self.doms = [list(f['domain']) for f in self.fields]
        self.cell_dom = [self.doms[c % self.F] for c in range(self.C)]
        self.sizes = [len(d) for d in self.cell_dom]
        self.strides = [1] * self.C
        acc = 1
        for c in range(self.C - 1, -1, -1):
            self.strides[c] = acc
            acc *= self.sizes[c]
        self.U = acc
        self.pred = job['predicates']
        self.masks = [self.predicate_mask(p) for p in self.pred]
        self.train = job['train']

    def cell(self, ref):
        return int(ref[0]) * self.F + self.names.index(ref[1])

    def decode(self, index):
        out = []
        rem = index
        for c in range(self.C):
            pos, rem = divmod(rem, self.strides[c])
            out.append(self.cell_dom[c][pos])
        return out

    def encode(self, flat):
        index = 0
        for c in range(self.C):
            index += self.cell_dom[c].index(flat[c]) * self.strides[c]
        return index

    def term(self, t, w):
        if 'const' in t:
            return int(t['const'])
        if 'sum' in t:
            total = 0
            for r in t['sum']:
                total += w[self.cell(r)]
            return total
        if 'scale' in t:
            return int(t['scale']) * w[self.cell(t['ref'])]
        return w[self.cell(t['ref'])]

    def holds(self, p, w):
        f = CMP[p['op']]
        if p['kind'] == 'cmp':
            return f(self.term(p['left'], w), self.term(p['right'], w))
        cells = [w[self.cell([s, p['field']])] for s in range(self.K)]
        if p['kind'] == 'any':
            return any(f(v, p['value']) for v in cells)
        return all(f(v, p['value']) for v in cells)

    def predicate_mask(self, p):
        mask = 0
        bit = 1
        for index in range(self.U):
            if self.holds(p, self.decode(index)):
                mask |= bit
            bit <<= 1
        return mask

    def train_mask(self, mask):
        out = 0
        for i, window in enumerate(self.train):
            flat = [v for row in window for v in row]
            if (mask >> self.encode(flat)) & 1:
                out |= 1 << i
        return out

    def rules(self):
        width = int(self.job_width)
        tmasks = [self.train_mask(m) for m in self.masks]
        full_t = (1 << len(self.train)) - 1
        full_u = (1 << self.U) - 1
        out = []
        for size in range(1, min(width, len(self.pred)) + 1):
            for clause in itertools.combinations(range(len(self.pred)), size):
                cover = 0
                for pid in clause:
                    cover |= tmasks[pid]
                if cover != full_t:
                    continue
                witnesses = []
                ok = True
                for pid in clause:
                    others = 0
                    for q in clause:
                        if q != pid:
                            others |= tmasks[q]
                    alone = tmasks[pid] & (full_t ^ others)
                    if not alone:
                        ok = False
                        break
                    witnesses.append((alone & -alone).bit_length() - 1)
                if not ok:
                    continue
                ucover = 0
                for pid in clause:
                    ucover |= self.masks[pid]
                if ucover == full_u:
                    continue
                gap = full_u & ~ucover
                out.append({'clause': list(clause), 'witnesses': witnesses,
                            'counterexample': (gap & -gap).bit_length() - 1})
        out.sort(key=lambda r: (len(r['clause']), r['clause']))
        return out

    def result(self, job):
        self.job_width = job['width']
        rules = self.rules()
        approved = {tuple(sorted(c)) for c in job['approved'] if c}
        active = [r['clause'] for r in rules if tuple(r['clause']) in approved]
        theory = (1 << self.U) - 1
        for clause in active:
            cover = 0
            for pid in clause:
                cover |= self.masks[pid]
            theory &= cover
        groups = {}
        for qi, q in enumerate(job['queries']):
            key = tuple(sorted((self.cell(b['ref']), int(b['value'])) for b in q['fixed']))
            groups.setdefault(key, []).append(qi)
        answers = [None] * len(job['queries'])
        for key, qids in groups.items():
            allowed = theory
            for cell, value in key:
                keep = 0
                bit = 1
                for index in range(self.U):
                    if self.decode(index)[cell] == value:
                        keep |= bit
                    bit <<= 1
                allowed &= keep
            stats = {}
            m = allowed
            while m:
                b = m & -m
                index = b.bit_length() - 1
                m ^= b
                for qi in qids:
                    cell = self.cell(job['queries'][qi]['target'])
                    value = self.decode(index)[cell]
                    entry = stats.setdefault((qi, value), [0, index])
                    entry[0] += 1
                    if index < entry[1]:
                        entry[1] = index
            for qi in qids:
                q = job['queries'][qi]
                prefix = str(q['prefix'])
                values = {v: c for (i, v), (c, _mn) in stats.items() if i == qi}
                count = sum(c for v, c in values.items() if str(v).startswith(prefix))
                cand = [mn for (i, v), (c, mn) in stats.items()
                        if i == qi and str(v).startswith(prefix)]
                tokens = [d for d in '0123456789'
                          if any(str(v).startswith(prefix + d) for v in values)]
                if prefix and any(str(v) == prefix for v in values):
                    tokens.append('END')
                answers[qi] = {'count': count, 'tokens': tokens,
                               'witness': min(cand) if cand else None}
        return {'rules': rules, 'active': active, 'answers': answers}


def ref2_job(job):
    return Ref(job).result(job)


def ref2_batch(batch):
    return {'results': [ref2_job(job) for job in batch['jobs']]}
