"""Differential fuzzing against the second (bitset) reference."""
import ctypes, json, random, sys, time
ctypes.CDLL('/workspace/vendor/system-libs/libz.so.1', mode=ctypes.RTLD_GLOBAL)
sys.path.insert(0, '/workspace/vendor'); sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace/dev')
from ref2 import ref2_batch
from gen import gen_batch
from netnomos.finite import compile_batch

def run(cases, seed0):
    bad = 0
    for i in range(cases):
        rng = random.Random(seed0 + i)
        batch = gen_batch(rng, jobs=rng.randint(1, 2), width=rng.randint(1, 4),
                          max_pred=rng.randint(3, 8), max_universe=400)
        want = ref2_batch(batch)
        got = compile_batch(batch)
        if got != want:
            bad += 1
            print('MISMATCH seed', seed0 + i)
            print(json.dumps(batch)[:5000])
            for a, b in zip(got['results'], want['results']):
                for key in ('rules', 'active', 'answers'):
                    if a[key] != b[key]:
                        print(' key', key)
                        print('  got ', json.dumps(a[key])[:2500])
                        print('  want', json.dumps(b[key])[:2500])
            if bad >= 1:
                break
    print('done ref2', cases, 'mismatches', bad)
    return bad

if __name__ == '__main__':
    n = int(sys.argv[1]); seed = int(sys.argv[2]) if len(sys.argv) > 2 else 90000
    sys.exit(1 if run(n, seed) else 0)
